# shellcheck shell=bash
# Powerlevel10k color overrides (dark), sourced after ~/.p10k.zsh.
# Output: ports/p10k/terminal-noir.p10k.zsh

build_p10k() {
    jq -r --arg q "'" '
        .variants.dark as $c
        | def p($k; $v): "typeset -g POWERLEVEL9K_\($k)=\($q)\($v)\($q)";
        "# Terminal Noir for Powerlevel10k. https://terminalnoir.web.app",
        "# Generated by scripts/build from palette/palette.json.",
        "# Source it right after ~/.p10k.zsh in your .zshrc.",
        "",
        "# Segment chrome",
        p("BACKGROUND"; $c.surface.elevated),
        p("MULTILINE_FIRST_PROMPT_GAP_FOREGROUND"; $c.surface.outline),
        p("LEFT_SUBSEGMENT_SEPARATOR"; "%F{\($c.text.faint)}\\uE0B1"),
        p("RIGHT_SUBSEGMENT_SEPARATOR"; "%F{\($c.text.faint)}\\uE0B3"),
        "",
        "# Left prompt",
        p("OS_ICON_FOREGROUND"; $c.accent.primary),
        p("DIR_FOREGROUND"; $c.text.primary),
        p("DIR_SHORTENED_FOREGROUND"; $c.text.muted),
        p("DIR_ANCHOR_FOREGROUND"; $c.accent.primary),
        p("PROMPT_CHAR_OK_{VIINS,VICMD,VIVIS,VIOWR}_FOREGROUND"; $c.accent.success),
        p("PROMPT_CHAR_ERROR_{VIINS,VICMD,VIVIS,VIOWR}_FOREGROUND"; $c.accent.error),
        "",
        "# Git",
        p("VCS_VISUAL_IDENTIFIER_COLOR"; $c.accent.success),
        p("VCS_LOADING_VISUAL_IDENTIFIER_COLOR"; $c.text.faint),
        p("VCS_CLEAN_FOREGROUND"; $c.accent.success),
        p("VCS_UNTRACKED_FOREGROUND"; $c.accent.success),
        p("VCS_MODIFIED_FOREGROUND"; $c.accent.warning),
        "",
        "# Right prompt",
        p("STATUS_OK_FOREGROUND"; $c.accent.success),
        p("STATUS_OK_PIPE_FOREGROUND"; $c.accent.success),
        p("STATUS_ERROR_FOREGROUND"; $c.accent.error),
        p("STATUS_ERROR_SIGNAL_FOREGROUND"; $c.accent.error),
        p("STATUS_ERROR_PIPE_FOREGROUND"; $c.accent.error),
        p("COMMAND_EXECUTION_TIME_FOREGROUND"; $c.text.muted),
        p("BACKGROUND_JOBS_FOREGROUND"; $c.ansi.bright.cyan),
        p("DIRENV_FOREGROUND"; $c.accent.warning),
        p("CONTEXT_ROOT_FOREGROUND"; $c.accent.error),
        p("CONTEXT_FOREGROUND"; $c.text.muted),
        p("TIME_FOREGROUND"; $c.text.muted)
    ' "$PALETTE" > "$OUT/ports/p10k/terminal-noir.p10k.zsh"
}
